    11	    private readonly IMoneyDispenser _dispenser = dispenser ?? throw new ArgumentNullException(nameof(dispenser));
    12	
    13	    public AtmResult Execute(AccountState account, Operation operation) => operation switch
    14	    {
    15	        Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
    16	        Operation.Deposit deposit => Deposit(account, deposit.Notes),
    17	        _ => throw new ArgumentException("Opération inconnue.", nameof(operation)),
    18	    };
    19	
    20	    private AtmResult Withdraw(AccountState account, int amount)
    21	    {
    22	        if (amount <= 0 || amount % 10 != 0)
    23	        {
    24	            return Refuse(AtmStatus.InvalidAmount, account);
    25	        }
    26	
    27	        if (account.WithdrawnToday + amount > DailyLimit)
    28	        {
    29	            return Refuse(AtmStatus.DailyLimitExceeded, account);
    30	        }
    31	
    32	        var fee = FeeFor(amount);
    33	        if (amount + fee > account.Balance)
    34	        {
    35	            return Refuse(AtmStatus.InsufficientFunds, account);
    36	        }
    37	
    38	        if (FewestNotes(amount, Available()) is not { } combination)
    39	        {
    40	            return Refuse(AtmStatus.CannotDispense, account);
    41	        }
    42	
    43	        var dispensed = NoteCounts.None;
    44	        foreach (var pass in Passes(combination))
    45	        {
    46	            if (!_dispenser.Dispense(pass))
    47	            {
    48	                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
    49	            }
    50	
    51	            dispensed += pass;
    52	        }
    53	
    54	        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);
    55	
    56	        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    57	    }
    58	
    59	    private AtmResult Deposit(AccountState account, NoteCounts notes)
    60	    {
    61	        if (notes.Total <= 0)
    62	        {
    63	            return Refuse(AtmStatus.InvalidAmount, account);
    64	        }
    65	
    66	        if (_dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
    67	        {
    68	            return Refuse(AtmStatus.CassetteJammed, account);
    69	        }
    70	
    71	        var after = _dispenser.Stock + notes;
    72	        if (after.Fifties > CassetteCapacity || after.Twenties > CassetteCapacity || after.Tens > CassetteCapacity)
    73	        {
    74	            return Refuse(AtmStatus.CassetteFull, account);
    75	        }
    76	
    77	        if (!_dispenser.Load(notes))
    78	        {
    79	            return Refuse(AtmStatus.DispenserFault, account);
    80	        }
    81	
    82	        return new AtmResult(
    83	            AtmStatus.Ok,
    84	            NoteCounts.None,
    85	            0,
    86	            account with { Balance = account.Balance + notes.Value });
    87	    }
    88	
    89	    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
    90	        new(status, NoteCounts.None, 0, account);
    91	
    92	    private static int FeeFor(int amount) => amount > FeeThreshold ? WithdrawalFee : 0;
    93	
    94	    /// <summary>Le stock utilisable : la cassette bloquée compte pour zéro.</summary>
    95	    private NoteCounts Available()
    96	    {
    97	        var stock = _dispenser.Stock;
    98	
    99	        return _dispenser.Jammed switch
   100	        {
   101	            Denomination.Fifty => stock with { Fifties = 0 },
   102	            Denomination.Twenty => stock with { Twenties = 0 },
   103	            Denomination.Ten => stock with { Tens = 0 },
   104	            _ => stock,
   105	        };
   106	    }
   107	
   108	    /// <summary>La combinaison qui fait exactement <paramref name="amount"/> avec le moins de billets, ou <c>null</c>.</summary>
   109	    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
   110	    {
   111	        NoteCounts? best = null;
   112	        for (var fifties = Math.Min(available.Fifties, amount / 50); fifties >= 0; fifties--)
   113	        {
   114	            var afterFifties = amount - fifties * 50;
   115	            for (var twenties = Math.Min(available.Twenties, afterFifties / 20); twenties >= 0; twenties--)
   116	            {
   117	                var rest = afterFifties - twenties * 20;
   118	                if (rest % 10 != 0 || rest / 10 > available.Tens)
   119	                {
   120	                    continue;
   121	                }
   122	
   123	                var candidate = new NoteCounts(fifties, twenties, rest / 10);
   124	                if (best is not { } current || candidate.Total < current.Total)
   125	                {
   126	                    best = candidate;
   127	                }
   128	            }
   129	        }
   130	
   131	        return best;
   132	    }
   133	
   134	    /// <summary>Découpe la combinaison en passages d'au plus <see cref="MaxNotesPerPass"/> billets.</summary>
   135	    private static IEnumerable<NoteCounts> Passes(NoteCounts notes)
   136	    {
   137	        var remaining = notes;
   138	        while (remaining.Total > 0)
   139	        {
   140	            var room = MaxNotesPerPass;
   141	            var fifties = Math.Min(remaining.Fifties, room);
   142	            room -= fifties;
   143	            var twenties = Math.Min(remaining.Twenties, room);
   144	            room -= twenties;
   145	            var tens = Math.Min(remaining.Tens, room);
   146	
   147	            var pass = new NoteCounts(fifties, twenties, tens);
   148	            remaining -= pass;
   149	
   150	            yield return pass;
   151	        }
   152	    }
   153	}
